import { useEffect, useState } from "react";

import AnalyticsCards from "./AnalyticsCards";
import ExpensePieChart from "./ExpensePieChart";
import IncomeExpenseChart from "./IncomeExpenseChart";
import SpendingTrend from "./SpendingTrend";
import TopCategories from "./TopCategories";
import MonthlySummary from "./MonthlySummary";

import { getIncome } from "../../api/incomeApi";
import { getExpenses } from "../../api/expenseApi";

const Analytics = () => {
  const [incomeList, setIncomeList] = useState([]);
  const [expenseList, setExpenseList] = useState([]);

  const fetchAnalytics = async () => {
    try {
      const [incomeRes, expenseRes] = await Promise.all([
        getIncome(),
        getExpenses(),
      ]);

      const incomes = incomeRes.data.incomes || [];
      const expenses = expenseRes.data.expenses || [];

      setIncomeList(incomes);
      setExpenseList(expenses);
    } catch (err) {
      console.error("Analytics Error:", err);
    }
  };

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const totalIncome = incomeList.reduce(
    (sum, item) => sum + Number(item.amount),
    0
  );

  const totalExpense = expenseList.reduce(
    (sum, item) => sum + Number(item.amount),
    0
  );

  const totalBalance = totalIncome - totalExpense;

  const totalTransactions =
    incomeList.length + expenseList.length;

  return (
    <div className="p-6 space-y-6 bg-slate-900 min-h-screen">
      <h1 className="text-3xl font-bold text-white">
        Analytics Dashboard
      </h1>

      <AnalyticsCards
        totalIncome={totalIncome}
        totalExpense={totalExpense}
        totalBalance={totalBalance}
        totalTransactions={totalTransactions}
      />

      <ExpensePieChart expenses={expenseList} />

      <IncomeExpenseChart
        incomes={incomeList}
        expenses={expenseList}
      />

      <SpendingTrend expenses={expenseList} />

      <TopCategories expenses={expenseList} />

      <MonthlySummary
        incomes={incomeList}
        expenses={expenseList}
      />
    </div>
  );
};

export default Analytics;